raw:
{
  "spells": [
    {
      "id": "spell_fire_04",
      "theory": "驯灶术把魔力压入柴薪或炭块内部，使燃烧只在灶膛浅层稳步推进，不向四周乱窜。施术者需理解灶膛的通风路径与燃料堆放方式，让魔力像一层薄壳裹住燃料，减缓其向内燃烧的速度。火候稳定后，同样一餐饭只需略少柴薪即可完成；但燃料本身仍是凡火所燃，离开灶膛后并无任何延烧优势。",
      "casting": "左手按灶沿，右手以指节在柴堆上方画三道短横，逐次送入魔力，待火色由跳红转稳黄即可。",
      "failure": "魔力送得太急会让火焰短暂蹿高，锅底一侧先焦；若横线画歪，火候忽大忽小，灶膛积炭却烧不透，需重新添柴。",
      "counters": [
        "用湿布盖住灶口可切断通风，让火势自然回落到普通燃烧。",
        "抽出几根柴薪打散堆叠，魔力薄壳随之破碎，稳定便消失。"
      ],
      "socialConsequences": "乡约见证下的分家、合伙做饭常请会此术的人来稳灶，省下的柴薪按约定均分。卖柴人不会因此饿肚子，因为省一成不等于不买柴；但若有人夸口能省更多，同行会当众要求他再烧一锅验证。城镇客栈的厨子欢迎它，却担心学徒借稳火之名把菜炖过头。港口灶船更看重它，因为甲板火盆一旦乱蹿，损失远不止柴钱。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚学会时火色仍会随添柴动作跳一下，需要盯着灶膛。",
        "熟练后能维持整锅汤面微沸，不必频繁抽添柴薪。",
        "可预判风向变化，在灶口来风前先调整燃料堆叠位置。",
        "极高熟练度下火候几乎不晃，仍只降低一成燃料消耗。"
      ]
    },
    {
      "id": "spell_fire_05",
      "theory": "炭纹测温在受测器具表面画一条炭粉细线，魔力沿炭粒传导，把器壁冷热差异转成线条颜色深浅与收缩快慢。施术者必须与器具保持直接接触，炭线也不可离开器面，因为热感靠炭粒间的接触传递，隔布、隔墙或远距读取都会断开通道。它读的是器壁温度，不是内部液体温度，读数需要施术者自己比对。",
      "casting": "拇指蘸炭粉在器壁上画一条短线，食指点住线尾，缓缓送入魔力，观察线条由黑转灰再转暗红。",
      "failure": "炭粉太厚会让整条线一起变色，分不出温差；若手指离开器壁，线色立刻停住，留下一条半灰半黑的痕迹，需擦掉重画。",
      "counters": [
        "往器壁上泼一层水膜，炭线被冲散便无法继续传导。",
        "用隔热布垫在施术者与器具之间，接触中断，读数立刻失效。"
      ],
      "socialConsequences": "河谷的酿酒户在乡约见证下用它检查发酵缸外壁，避免伸手入缸污染酒醅。城镇铁匠铺用它在淬火前确认刀坯温度，但公会要求炭线不得画在客人的成品器皿上，以免留下焦痕。琥珀海岸的货主欢迎它检查船舱里的油罐，港务规定却要求读数只作参考，不能替代开舱验货，免得有人借一条灰线推卸货损责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时线条颜色变化很慢，常把温与烫混为一谈。",
        "熟练后能分辨微温与烫手之间的差别，减少误判。",
        "可凭线条收缩速度判断器壁哪一侧更热，仍须接触。",
        "极高熟练度下读数更快更稳，隔布隔墙依旧无效。"
      ]
    },
    {
      "id": "spell_fire_06",
      "theory": "火线术把魔力灌入地面浅层的可燃碎屑与空气交界处，使一条两米长的火线沿地表维持燃烧，形成阻挡行路的低矮火墙。火焰贴着地面，不向两侧蔓延，也不主动追逐目标；它靠地面燃料和空气维持，因此水浇、覆土或抽走碎屑都能让它熄灭。火线本身不选择敌我，任何人踏入都会受伤。",
      "casting": "弯腰以指尖沿地面画一条两米直线，指腹压住起点送入魔力，待线头冒出蓝黄火苗后收手退开。",
      "failure": "指尖移动过快会让火线断成几截，断口处只剩焦痕；若地面潮湿，魔力只烫出一缕白烟，火线根本不成形。",
      "counters": [
        "提一桶水从起点浇到终点，火线遇水即灭，只剩湿灰。",
        "用铁锹铲走燃烧的碎屑层，火线失去燃料便自行熄灭。"
      ],
      "socialConsequences": "河谷赶牲畜的人偶用它在岔路口临时拦牛，但乡约会要求施术者站在旁边看管，烧到别人庄稼另算赔偿。城镇巡夜队不喜欢平民在街巷放火线，认为它容易吓到马匹；公会许可的护卫可在仓库区外围短时使用，事后必须清理焦痕。琥珀海岸的码头更谨慎，港务规定火线不得靠近油桶与缆绳，一旦引发货损，责任按航运事故追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "刚学会时火线常歪斜，长度也容易超出或不足两米。",
        "熟练后线形更直，边缘火花较少，仍须贴近地面。",
        "可控制火苗高低，让火线在湿地上多维持片刻。",
        "极高熟练度下火线两端收束干净，范围仍只有两米。"
      ]
    }
  ]
}
